1	import { useState, useRef, useEffect } from "react";
2	import { useQuery } from "@tanstack/react-query";
3	import { useLocation } from "wouter";
4	import { propFetch } from "@/lib/property-api";
5	import {
6	  type Timeframe, buildBuckets, periodWindow, collectedCents,
7	  growthPct, collectionRate, filterByProperty, fmtCompact,
8	} from "@/lib/property-dashboard-data";
9	
10	/* ── Design tokens ── */
11	const NAVY = '#040D6D';
12	const SKY  = '#58ABFF';
13	const BAR  = 'rgba(88,171,255,0.72)';   // resting bar
14	const SEL  = '#58ABFF';                  // selected bar (full sky)
15	const SHEET = '#F4F4F4';
16	
17	const TIMEFRAMES: Timeframe[] = ['day', 'week', 'month', 'year'];
18	
19	const fmtWhole = (c: number) => '$' + Math.round(c / 100).toLocaleString('en-NZ');
20	
21	/* ── Icons ── */
22	const IcoPlus  = () => <svg width={22} height={22} viewBox="0 0 24 24" fill="none" stroke={NAVY} strokeWidth="2.2" strokeLinecap="round"><path d="M12 5v14M5 12h14"/></svg>;
23	const IcoBell  = () => <svg width={20} height={20} viewBox="0 0 24 24" fill="none" stroke={NAVY} strokeWidth="1.9" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="13" r="7"/><path d="M12 10v3l2 2"/><path d="M5 4 3 6M19 4l2 2"/></svg>;
24	const IcoBill  = () => <svg width={20} height={20} viewBox="0 0 24 24" fill="none" stroke={NAVY} strokeWidth="1.9" strokeLinecap="round" strokeLinejoin="round"><path d="M6 3h12v18l-3-2-3 2-3-2-3 2z"/><path d="M9 8h6M9 12h6"/></svg>;
25	const IcoPeeps = () => <svg width={20} height={20} viewBox="0 0 24 24" fill={NAVY}><circle cx="8.5" cy="8" r="3"/><circle cx="16" cy="8.5" r="2.4"/><path d="M2.6 19c0-3.2 2.6-5.6 5.9-5.6s5.9 2.4 5.9 5.6z"/><path d="M15.4 13.6c2.6.2 4.9 2.3 4.9 5.1z"/></svg>;
26	const IcoWarn  = () => <svg width={20} height={20} viewBox="0 0 24 24" fill="none" stroke={SKY} strokeWidth="1.8" strokeLinecap="round"><circle cx="12" cy="12" r="9"/><path d="M12 7.5v5"/><circle cx="12" cy="15.8" r=".9" fill={SKY} stroke="none"/></svg>;
27	const IcoChev  = () => <svg width={12} height={12} viewBox="0 0 24 24" fill="none" stroke={SKY} strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><path d="M6 9l6 6 6-6"/></svg>;
28	
29	/* Press → one stroke-glow ring pulse. Remove+reflow+re-add restarts the CSS animation. */
30	function pulse(e: React.PointerEvent<HTMLElement>) {
31	  const el = e.currentTarget;
32	  el.classList.remove('pd-pulse');
33	  void el.offsetWidth; // force reflow so the animation restarts
34	  el.classList.add('pd-pulse');
35	}
36	
37	/* ── Property filter dropdown — wireframe pill + menu ── */
38	function PropertyDropdown({ options, value, onPick }: {
39	  options: string[]; value: string | null; onPick: (v: string | null) => void;
40	}) {
41	  const [open, setOpen] = useState(false);
42	  const rootRef = useRef<HTMLDivElement>(null);
43	
44	  useEffect(() => {
45	    if (!open) return;
46	    const close = (e: PointerEvent) => {
47	      if (!rootRef.current?.contains(e.target as Node)) setOpen(false);
48	    };
49	    document.addEventListener('pointerdown', close);
50	    return () => document.removeEventListener('pointerdown', close);
51	  }, [open]);
52	
53	  return (
54	    <div ref={rootRef} style={{ position: 'relative', zIndex: 20 }}>
55	      <button type="button" className="pd-tap" onPointerDown={pulse} onClick={() => setOpen(o => !o)}
56	        style={{ display: 'inline-flex', alignItems: 'center', gap: 8, padding: '8px 16px', borderRadius: 999, background: 'transparent', border: `1.5px solid ${SKY}`, color: SKY, fontWeight: 500, fontSize: 13, cursor: 'pointer', fontFamily: 'Outfit, system-ui', WebkitTapHighlightColor: 'transparent' }}>
57	        <span style={{ maxWidth: 140, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{value ?? 'all properties'}</span>
58	        <span style={{ transform: open ? 'rotate(180deg)' : 'none', transition: 'transform 0.2s', display: 'flex' }}><IcoChev /></span>
59	      </button>
60	      {open && (
61	        <div style={{ position: 'absolute', top: 'calc(100% + 8px)', right: 0, minWidth: 200, maxHeight: 260, overflowY: 'auto', background: NAVY, border: `1.5px solid rgba(88,171,255,0.4)`, borderRadius: 16, padding: 6, boxShadow: '0 16px 40px rgba(0,0,0,0.35)' }}>
62	          {[null, ...options].map(opt => (
63	            <button key={opt ?? '__all'} type="button"
64	              onClick={() => { onPick(opt); setOpen(false); }}
65	              style={{ display: 'block', width: '100%', textAlign: 'left', padding: '10px 14px', borderRadius: 11, border: 'none', cursor: 'pointer', fontFamily: 'Outfit, system-ui', fontSize: 13, fontWeight: (value ?? null) === opt ? 700 : 400, background: (value ?? null) === opt ? 'rgba(88,171,255,0.16)' : 'transparent', color: SKY, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
66	              {opt ?? 'all properties'}
67	            </button>
68	          ))}
69	        </div>
70	      )}
71	    </div>
72	  );
73	}
74	
75	/* ── Timeframe selector — sliding indicator, terminal SubBar pattern ── */
76	function TimeframeBar({ tf, onPick }: { tf: Timeframe; onPick: (t: Timeframe) => void }) {
77	  const btnRefs = useRef<(HTMLButtonElement | null)[]>([]);
78	  const mounted = useRef(false);
79	  const [ind, setInd] = useState({ x: 0, w: 0, on: false });
80	  const [animate, setAnim] = useState(false);
81	  const activeIdx = TIMEFRAMES.indexOf(tf);
82	
83	  useEffect(() => {
84	    const tick = () => {
85	      const el = btnRefs.current[activeIdx];
86	      if (el) setInd({ x: el.offsetLeft, w: el.offsetWidth, on: true });
87	    };
88	    if (!mounted.current) {
89	      requestAnimationFrame(() => requestAnimationFrame(() => { tick(); mounted.current = true; }));
90	    } else {
91	      setAnim(true);
92	      requestAnimationFrame(() => requestAnimationFrame(() => requestAnimationFrame(tick)));
93	      const t = setTimeout(() => setAnim(false), 520);
94	      return () => clearTimeout(t);
95	    }
96	  }, [activeIdx]);
97	
98	  return (
99	    <div style={{ display: 'flex', justifyContent: 'center' }}>
100	      <div style={{ position: 'relative', display: 'flex', alignItems: 'center', background: NAVY, borderRadius: 999, padding: 4, boxShadow: '0 6px 18px rgba(4,13,109,0.22)' }}>
101	        <div className={`pd-tf-ind${animate ? ' animate' : ''}`}
102	          style={{ position: 'absolute', top: 4, bottom: 4, left: ind.x, width: ind.w, borderRadius: 999, background: SKY, opacity: ind.on ? 1 : 0 }} />
103	        {TIMEFRAMES.map((t, i) => (
104	          <button key={t} type="button" ref={el => (btnRefs.current[i] = el)}
105	            className="pd-tap" onPointerDown={pulse}
106	            onClick={() => onPick(t)}
107	            style={{ position: 'relative', zIndex: 1, padding: '8px 18px', borderRadius: 999, border: 'none', background: 'transparent', cursor: 'pointer', fontFamily: 'Outfit, system-ui', fontWeight: 600, fontSize: 12.5, textTransform: 'capitalize', color: tf === t ? NAVY : 'rgba(88,171,255,0.75)', transition: 'color 0.25s ease', WebkitTapHighlightColor: 'transparent' }}>
108	            {t}
109	          </button>
110	        ))}
111	      </div>
112	    </div>
113	  );
114	}
115	
116	/* ── Bar chart — clickable, animates between timeframes ── */
117	const MAX_SLOTS = 12;
118	
119	function RentBarChart({ buckets, selectedIdx, onSelectBar, animKey }: {
120	  buckets: { label: string; valueCents: number }[];
121	  selectedIdx: number;
122	  onSelectBar: (i: number) => void;
123	  animKey: string;
124	}) {
125	  const W = 375, CH = 190, LABEL_H = 30, H = CH + LABEL_H, PADX = 10, BASE = CH;
126	  const n = buckets.length;
127	  const gap = n > 8 ? 8 : 14;
128	  const bw = (W - PADX * 2 - gap * (n - 1)) / n;
129	  const x = (i: number) => PADX + i * (bw + gap);
130	
131	  const [reveal, setReveal] = useState(false);
132	  useEffect(() => { const t = setTimeout(() => setReveal(true), 60); return () => clearTimeout(t); }, []);
133	
134	  const maxVal = Math.max(...buckets.map(b => b.valueCents), 1);
135	  const hOf = (v: number) => v <= 0 ? 6 : 12 + (v / maxVal) * (CH - 40);
136	
137	  const sel = buckets[selectedIdx];
138	  const selX = x(Math.min(selectedIdx, n - 1)) + bw / 2;
139	  const selTop = BASE - hOf(sel?.valueCents ?? 0);
140	
141	  return (
142	    <div style={{ position: 'relative', margin: '22px -6px 0' }}>
143	      <svg viewBox={`0 0 ${W} ${H}`} width="100%" style={{ display: 'block', height: 'auto', overflow: 'visible' }}>
144	        {Array.from({ length: MAX_SLOTS }, (_, i) => {
145	          const active = i < n;
146	          const bh = active && reveal ? hOf(buckets[i].valueCents) : 0;
147	          const bx = active ? x(i) : W - PADX - bw;
148	          return (
149	            <rect key={i} className="pd-bar"
150	              x={bx} width={Math.max(bw, 1)}
151	              y={BASE - bh} height={bh}
152	              rx={Math.min(7, bw / 2.4)}
153	              fill={i === selectedIdx ? SEL : BAR}
154	              style={{ cursor: active ? 'pointer' : 'default', pointerEvents: active ? 'auto' : 'none' }}
155	              onClick={() => active && onSelectBar(i)}
156	            />
157	          );
158	        })}
159	        {buckets.map((b, i) => (
160	          <text key={`${animKey}-${i}`} className="pd-bar-label"
