61	  saving: boolean;
62	  saveError: string | null;
63	}) {
64	  const [form, setForm] = useState({
65	    firstName: '', lastName: '', email: '', phone: '',
66	    propertyAddress: '', preferredChannel: 'email' as 'email' | 'whatsapp' | 'sms',
67	  });
68	  const [subtenants, setSubtenants] = useState<{ name: string; email: string; phone: string }[]>([]);
69	  const [subForm, setSubForm]       = useState({ name: '', email: '', phone: '' });
