206	
207	            {/* Add subtenant toggle button */}
208	            <button
209	              onClick={() => setSubOpen(o => !o)}
210	              style={{ width: '100%', padding: '13px 0', borderRadius: 14, border: `1.5px dashed ${subOpen ? C.sky : 'rgba(4,13,109,0.18)'}`, background: subOpen ? 'rgba(88,171,255,0.06)' : 'transparent', color: C.navy, fontWeight: 600, fontSize: 14, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8, transition: 'all 0.22s ease' }}>
211	              <svg width={16} height={16} viewBox="0 0 24 24" fill="none" stroke={C.sky} strokeWidth="2.4" strokeLinecap="round"><path d="M12 5v14M5 12h14"/></svg>
212	              <span style={{ color: C.navy }}>add subtenant</span>
213	            </button>
214	
215	            {/* Expandable subtenant form — smooth slide */}
216	            <div style={{
217	              overflow: 'hidden',
218	              maxHeight: subOpen ? '320px' : '0px',
219	              transition: 'max-height 0.38s cubic-bezier(0.16,1,0.3,1)',
