222	                <Field label="name" value={subForm.name} onChange={setSub('name')} required />
223	                <Field label="email" value={subForm.email} onChange={setSub('email')} type="email" />
224	                <Field label="phone" value={subForm.phone} onChange={setSub('phone')} type="tel" />
225	                <button
226	                  onClick={confirmSubtenant}
227	                  disabled={!subForm.name.trim()}
228	                  style={{ padding: '13px 0', borderRadius: 14, background: subForm.name.trim() ? C.navy : C.gray, color: subForm.name.trim() ? C.white : C.mute, fontWeight: 600, fontSize: 14, border: 'none', cursor: subForm.name.trim() ? 'pointer' : 'default', transition: 'background 0.18s' }}>
229	                  confirm subtenant
230	                </button>
231	              </div>
232	            </div>
233	          </div>
234	
235	          {/* Error */}
236	          {saveError && (
237	            <div style={{ marginBottom: 16, padding: '12px 16px', borderRadius: 14, background: 'rgba(255,59,78,0.07)', border: '1px solid rgba(255,59,78,0.18)' }}>
238	              <p style={{ color: '#C71A2A', fontSize: 13, fontWeight: 500, margin: 0 }}>{saveError}</p>
239	            </div>
240	          )}
241	
242	          {/* Save */}
243	          <button
244	            onClick={handleSave}
245	            disabled={!valid || saving}
246	            style={{ width: '100%', padding: '18px 0', borderRadius: 999, background: valid && !saving ? C.navy : C.gray, color: valid && !saving ? C.white : C.mute, fontWeight: 700, fontSize: 16, border: 'none', cursor: valid && !saving ? 'pointer' : 'default', transition: 'background 0.2s, color 0.2s' }}>
247	            {saving ? 'adding…' : 'add tenant'}
248	          </button>
249	        </div>
250	      </div>
251	      </div>
252	    </div>
253	  );
254	}
255	
256	/* ── Tenant list row ── */
257	function initials(tenant: any) {
258	  return `${tenant.firstName?.[0] ?? ''}${tenant.lastName?.[0] ?? ''}`.toUpperCase() || '?';
259	}
260	
261	function invoiceStatus(nextInvoice: any) {
262	  if (!nextInvoice) return 'upcoming';
263	  if (nextInvoice.status === 'paid' || nextInvoice.status === 'paid_external') return 'paid';
264	  if (nextInvoice.status === 'overdue') return 'overdue';
265	  if (nextInvoice.dueAt) {
266	    const due = new Date(nextInvoice.dueAt).getTime();
267	    const soon = Date.now() + 5 * 24 * 60 * 60 * 1000;
268	    if (!Number.isNaN(due) && due <= soon) return 'dueSoon';
269	  }
270	  return 'upcoming';
271	}
272	
273	function fmtDue(nextInvoice: any) {
274	  if (!nextInvoice?.dueAt) return 'no invoice';
275	  return new Date(nextInvoice.dueAt).toLocaleDateString('en-NZ', { day: '2-digit', month: 'short' }).toUpperCase();
276	}
277	
278	function TenantRow({ tenant, nextInvoice, onClick }: { tenant: any; nextInvoice: any; onClick: () => void }) {
279	  const fullName = `${tenant.firstName} ${tenant.lastName}`.trim();
280	  const status = invoiceStatus(nextInvoice);
281	  const s = STATUS_MAP[status] ?? STATUS_MAP.upcoming;
282	
283	  return (
284	    <button type="button" className="tdir-row" onClick={onClick}>
285	      <span className="tdir-avatar">{initials(tenant)}</span>
286	      <span className="tdir-copy">
287	        <span className="tdir-name">{fullName}</span>
288	        <span className="tdir-address">{tenant.propertyAddress}</span>
289	        <span className="tdir-status" style={{ color: s.fg }}>
290	          <span style={{ background: s.dot }} />
291	          {s.label}
292	        </span>
293	      </span>
294	      <span className="tdir-money">
295	        <span>{nextInvoice ? fmtCents(nextInvoice.amountCents) : '$0.00'}</span>
296	        <small>{fmtDue(nextInvoice)}</small>
297	      </span>
298	    </button>
299	  );
300	}
301	
302	export default function TenantDirectory() {
303	  const [, setLocation] = useLocation();
304	  const [search,    setSearch]    = useState('');
305	  const [showAdd,   setShowAdd]   = useState(false);
306	  const [showArchived, setShowArchived] = useState(false);
307	  const [saveError, setSaveError] = useState<string | null>(null);
308	  const queryClient = useQueryClient();
309	  const heroRef = useRef<HTMLDivElement>(null);
310	
311	  // Signal the hero is mounted so a reverse hero-morph (profile → directory)
312	  // can capture and play (see property-transition.ts).
313	  useLayoutEffect(() => { signalPropertyReady(); }, []);
314	
315	  const { data: tenants = [], isLoading } = useQuery<any[]>({
316	    queryKey: ['/api/property/tenants'],
317	    queryFn: () => propFetch('/api/property/tenants').then(r => r.ok ? r.json() : []),
318	    staleTime: 60000,
319	    retry: false,
320	  });
321	
322	  const { data: invoices = [] } = useQuery<any[]>({
323	    queryKey: ['/api/property/invoices'],
324	    queryFn: () => propFetch('/api/property/invoices').then(r => r.ok ? r.json() : []),
325	    staleTime: 30000,
326	    retry: false,
327	  });
328	
329	  // Archived tenants — fetched lazily only when the merchant expands the section.
330	  const { data: archivedTenants = [] } = useQuery<any[]>({
331	    queryKey: ['/api/property/tenants', 'archived'],
332	    queryFn: () => propFetch('/api/property/tenants?includeArchived=true').then(r => r.ok ? r.json() : []),
333	    select: (list: any[]) => list.filter((t: any) => t.status === 'archived'),
334	    enabled: showArchived,
335	    staleTime: 30000,
336	    retry: false,
337	  });
338	
339	  const restoreMutation = useMutation({
340	    mutationFn: async (id: string) => {
341	      const r = await fetch(`/api/property/tenants/${id}/unarchive`, { method: 'POST', headers: propHeaders() });
342	      if (!r.ok) throw new Error('Failed to restore');
343	      return r.json();
344	    },
345	    onSuccess: () => { queryClient.invalidateQueries({ queryKey: ['/api/property/tenants'] }); },
346	  });
347	
348	  const createMutation = useMutation({
349	    mutationFn: async (data: any) => {
350	      const r = await fetch('/api/property/tenants', {
351	        method: 'POST',
352	        headers: { 'Content-Type': 'application/json', ...propHeaders() },
353	        body: JSON.stringify(data),
354	      });
355	      if (!r.ok) {
356	        const msg = await r.json().then(d => d.message).catch(() => `Error ${r.status}`);
357	        throw new Error(msg);
358	      }
359	      return r.json();
360	    },
361	    onSuccess: () => {
362	      queryClient.invalidateQueries({ queryKey: ['/api/property/tenants'] });
363	      setSaveError(null);
364	      setShowAdd(false);
365	    },
366	    onError: (err: any) => {
367	      setSaveError(err?.message || 'Failed to add tenant. The backend may not be connected yet.');
368	    },
369	  });
370	
371	  /* Helpers */
372	  const activeTenants = tenants.filter((t: any) => t.status !== 'archived');
373	  const term = search.trim().toLowerCase();
374	  const filtered = activeTenants.filter((t: any) =>
375	    !term || `${t.firstName} ${t.lastName}`.toLowerCase().includes(term) || t.propertyAddress.toLowerCase().includes(term)
376	  );
377	  const tenantCountLabel = `active tenant${activeTenants.length !== 1 ? 's' : ''}`;
378	
379	  // Return the invoice that represents the worst-case status for this tenant
380	  // (overdue > dispatched/pending > paid). Fallback to most recent for display.
381	  const invoiceByTenant = (tenantId: string) => {
382	    const live = invoices.filter((i: any) => i.tenantProfileId === tenantId && i.status !== 'voided');
383	    if (live.length === 0) return undefined;
384	    const overdue = live.find((i: any) => i.status === 'overdue');
385	    if (overdue) return overdue;
386	    const pending = live.find((i: any) => ['dispatched', 'pending_dispatch', 'dispatch_failed'].includes(i.status));
387	    if (pending) return pending;
388	    return [...live].sort((a: any, b: any) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())[0];
389	  };
390	
391	  return (
392	    <div style={{ background: C.white, minHeight: '100svh', display: 'flex', justifyContent: 'center' }}>
393	    <div style={{ width: '100%', maxWidth: 369, minHeight: '100svh', background: C.sheet, paddingBottom: 128, fontFamily: "'Outfit', system-ui, sans-serif", overflow: 'hidden' }}>
394	      <style>{DIRECTORY_CSS}</style>
395	
396	      {/* Hero — carries view-transition-name so it morphs into the profile hero */}
397	      <section ref={heroRef} className="pt-hero tdir-hero">
398	        <div className="tdir-hero-count">{activeTenants.length}</div>
399	        <div className="tdir-hero-label">{tenantCountLabel}</div>
400	        <button type="button" className="tdir-add" onPointerDown={pulse} onClick={() => setShowAdd(true)} aria-label="Add tenant">
401	          <svg width={31} height={31} viewBox="0 0 24 24" fill="none" stroke={C.navy} strokeWidth="2.3" strokeLinecap="round"><path d="M12 5v14M5 12h14" /></svg>
402	        </button>
403	      </section>
404	
405	      <main className="tdir-body">
406	        <div className="tdir-search-row">
407	          <label className="tdir-search">
408	            <svg width={17} height={17} viewBox="0 0 24 24" fill="none" stroke={C.navy} strokeWidth="2" strokeLinecap="round"><circle cx="11" cy="11" r="6.5" /><path d="m20 20-3.5-3.5" /></svg>
409	            <input
410	              value={search}
411	              onChange={e => setSearch(e.target.value)}
412	              placeholder="search tenants or address"
413	            />
414	            {search && (
415	              <button type="button" onClick={() => setSearch('')} aria-label="Clear search">
416	                <svg width={15} height={15} viewBox="0 0 24 24" fill="none" stroke={C.mute} strokeWidth="2.2" strokeLinecap="round"><path d="M6 6l12 12M18 6 6 18" /></svg>
417	              </button>
418	            )}
419	          </label>
420	          <button
421	            type="button"
422	            onClick={() => startPropertyBack(() => setLocation('/property'), { expectHero: false })}
423	            aria-label="Go to property dashboard"
424	            className="tdir-grid-btn"
425	          >
426	            <svg width={20} height={20} viewBox="0 0 20 20" fill={C.sky}><rect x="1" y="1" width="7" height="7" rx="2" /><rect x="12" y="1" width="7" height="7" rx="2" /><rect x="1" y="12" width="7" height="7" rx="2" /><rect x="12" y="12" width="7" height="7" rx="2" /></svg>
427	          </button>
428	        </div>
429	
430	        <div className="tdir-list">
431	          {isLoading ? (
432	            <div className="tdir-empty">loading tenants...</div>
433	          ) : filtered.length === 0 ? (
434	            <div className="tdir-empty">
435	              {search ? `no tenants match "${search}"` : 'no tenants yet - tap + to add your first'}
436	            </div>
437	          ) : (
438	            filtered.map((t: any) => (
439	              <TenantRow
440	                key={t.id}
441	                tenant={t}
442	                nextInvoice={invoiceByTenant(t.id)}
443	                onClick={() => {
444	                  const inv = invoiceByTenant(t.id);
445	                  startPropertyNavigation(
446	                    {
447	                      id: t.id,
448	                      firstName: t.firstName,
449	                      lastName: t.lastName,
450	                      propertyAddress: t.propertyAddress,
451	                      preferredChannel: t.preferredChannel,
452	                      invoiceStatus: inv?.status,
453	                    },
454	                    () => setLocation(`/property/tenants/${t.id}`)
455	                  );
456	                }}
457	              />
458	            ))
459	          )}
460	        </div>
461	
462	        <div className="tdir-archived">
463	          <button type="button" onClick={() => setShowArchived(s => !s)}>
464	            {showArchived ? 'hide archived' : 'show archived'}
465	          </button>
466	          {showArchived && (
467	            archivedTenants.length === 0 ? (
468	              <div className="tdir-archived-empty">no archived tenants</div>
469	            ) : (
470	              <div className="tdir-archived-list">
471	                {archivedTenants.map((t: any) => (
472	                  <div key={t.id} className="tdir-archive-row">
473	                    <div>
474	                      <strong>{t.firstName} {t.lastName}</strong>
475	                      <span>{t.propertyAddress}</span>
476	                    </div>
477	                    <button type="button" onClick={() => restoreMutation.mutate(t.id)} disabled={restoreMutation.isPending}>restore</button>
478	                  </div>
479	                ))}
480	              </div>
481	            )
482	          )}
483	        </div>
484	      </main>
485	
486	      {/* Add tenant sheet */}
487	      {showAdd && (
488	        <AddTenantSheet
489	          onClose={() => { setShowAdd(false); setSaveError(null); }}
490	          onSave={data => { setSaveError(null); createMutation.mutate(data); }}
491	          saving={createMutation.isPending}
492	          saveError={saveError}
493	        />
494	      )}
495	    </div>
496	    </div>
497	  );
498	}
