   buckets are rolling so the last one is always current; the calendar
   timeframes can have future buckets (rest of the week/month/year). */
export function currentBucketIdx(tf: Timeframe, now = new Date()): number {
  if (tf === 'day') return 7;
  if (tf === 'week') return (now.getDay() + 6) % 7;              // Monday-start
  if (tf === 'month') return Math.floor((now.getDate() - 1) / 7);
  return now.getMonth();
}

